fases.solucionReferencia:
def cuadrado(n):
    return n * n
def mitad(n):
    return n // 2
print(mitad(cuadrado(6)))

def quitar_dos(n):
    return n - 2
def duplicar(n):
    return n * 2
def sumar_tres(n):
    return n + 3
print(sumar_tres(duplicar(quitar_dos(10))))
